            ['section' => 'Comprehension', 'type' => 'mcq', 'question_text' => 'What was Behrman\'s masterpiece?', 'option_a' => 'A painted ivy leaf that never fluttered or fell', 'option_b' => 'A portrait of the two young women above his rooms', 'option_c' => 'A landscape of the Bay of Naples', 'option_d' => 'The fresco he sold that very morning', 'correct_option' => 'a'],
            ['section' => 'Comprehension', 'type' => 'identification', 'question_text' => 'What objects found below hinted where Behrman had been on the stormy night? Name any one of them.', 'acceptable_answers' => ['a lantern still lighted', 'lantern', 'a ladder', 'ladder', 'scattered brushes', 'brushes', 'a palette with green and yellow colors', 'palette']],
